SAMPLES_DIR = Path(__file__).resolve().parents[2] / "data" / "samples"
MESSY = SAMPLES_DIR / "messy_classification.csv"


def test_clean_dedup_and_dtype_fix() -> None:
    frame = pd.DataFrame({"a": ["1", "1", "N/A"], "b": ["x", "x", " y "]})
    out, report = dedupe_and_fix_dtypes(frame)
    assert report.rows_before == 3
    assert report.rows_after == 2
    assert report.duplicates_removed == 1
    assert report.sentinels_replaced == 1
    assert is_numeric_dtype(out["a"])
    assert int(out["a"].isna().sum()) == 1
    assert out["b"].tolist() == ["x", "y"]

    messy = pd.read_csv(MESSY)
    _, messy_report = dedupe_and_fix_dtypes(messy)
    assert messy_report.rows_before == 195
    assert messy_report.duplicates_removed == 15
    assert messy_report.rows_after == 180


def test_clean_never_imputes_target() -> None:
    frame = pd.DataFrame({"x": [1.0, None, 3.0], "y": [0, 1, None]})
    with pytest.raises(TaskError):
        apply_imputation(frame, ["y"], "median", target="y")

    out = drop_missing_target(frame, "y")
    assert len(out) == 2
    assert out["y"].notna().all()

    filled = apply_imputation(frame, ["x"], "median", target="y")
    assert int(filled["x"].isna().sum()) == 0
    assert filled["y"].isna().astype(bool).tolist() == [False, False, True]
    assert filled["y"].iloc[:2].tolist() == [0.0, 1.0]


def test_clean_nan_policy_by_capability() -> None:
    required = nan_decision(handles_nan=False)
    assert required.imputation_required is True
    assert required.allow_leave_nan is False
    assert set(required.strategies) == {"median", "mean", "knn", "iterative", "mode", "constant"}

    flexible = nan_decision(handles_nan=True)
    assert flexible.imputation_required is False
    assert flexible.allow_leave_nan is True

    frame = pd.DataFrame({"a": [1.0, None], "b": ["x", "y"]})
    assert columns_with_missing(frame) == ["a"]
    assert columns_with_missing(frame, exclude=["a"]) == []


def test_clean_no_outlier_removal_anomaly() -> None:
    decision = outlier_decision("anomaly_detection", "density")
    assert decision.rule_id == "CLEAN-04a"
    assert "remove" not in decision.allowed
    assert "drop" not in decision.allowed
    assert decision.default == "flag"

    frame = pd.DataFrame({"v": [1.0, 2.0, 3.0, 1000.0]})
    with pytest.raises(TaskError):
        apply_outlier_treatment(frame, ["v"], "drop")
    flagged = apply_outlier_treatment(frame, ["v"], "flag")
    assert len(flagged) == len(frame)
    assert int(flagged["v_outlier"].sum()) == 1


def test_clean_outliers_keep_and_flag_trees() -> None:
    decision = outlier_decision("regression", "tree")
    assert decision.rule_id == "CLEAN-04b"
    assert decision.default == "flag"
    assert tuple(decision.allowed) == ("keep", "flag")


def test_clean_outlier_treatment_recommended() -> None:
    decision = outlier_decision("regression", "linear")
    assert decision.rule_id == "CLEAN-04c"
    assert decision.default == "keep"
    assert "clip" in decision.allowed
    assert "winsorize" in decision.allowed
    assert "robust scaling" in decision.recommend

    frame = pd.DataFrame({"v": [1.0, 2.0, 3.0, 1000.0]})
    assert apply_outlier_treatment(frame, ["v"], "keep").equals(frame)
    clipped = apply_outlier_treatment(frame, ["v"], "clip")
    assert clipped["v"].max() < 1000.0
    winsorized = apply_outlier_treatment(frame, ["v"], "winsorize")
    assert winsorized["v"].max() < 1000.0


def test_clean_flag_minority_under_20_pct() -> None:
    frame = pd.DataFrame({"x": [1.0] * 20, "y": ["a"] * 19 + ["b"]})
    balance = class_balance(frame, "y", "binary")
    assert isinstance(balance, ClassBalance)
    assert balance.imbalanced is True
    assert balance.minority_fraction == pytest.approx(0.05)
    assert balance.counts == {"a": 19, "b": 1}

    framed = pd.DataFrame({"y": ["a"] * 12 + ["b"] * 8})
    balanced = class_balance(framed, "y", "binary")
    assert balanced is not None
    assert balanced.imbalanced is False

    assert class_balance(frame, "y", "regression") is None


def test_clean_undo_restores_counts(tmp_path: Path) -> None:
    workspace = Workspace(project_id="p_undo", root=tmp_path)
    state = ProjectState(project_id="p_undo")

    messy = pd.read_csv(MESSY)
    insert_dataset(state, workspace, messy, source="sample:messy_classification.csv")
    before = len(state.frame)
    assert state.dataset is not None
    loads = [step for step in state.steps if step.tab == "data"]
    assert len(loads) == 1 and loads[0].op == "load"

    state.task = build_task(messy, "supervised", target="churned")
    result = run_cleaning(state, workspace, CleaningOptions())

    assert result.rows_before == before == 195
    assert result.rows_after < before
    cleaning_entries = [step for step in state.steps if step.tab == "cleaning"]
    assert cleaning_entries
    for entry in cleaning_entries:
        assert entry.dataset_hash_before.startswith("sha256:")
        assert entry.dataset_hash_after.startswith("sha256:")
        assert "version_before" in entry.params
        assert "version_after" in entry.params

    undone = undo_last_cleaning_step(state, workspace)
    assert undone is not None and undone.tab == "cleaning"
    assert undone.id not in {step.id for step in state.steps}
    assert state.dataset is not None and state.dataset.version == undone.params["version_before"]
    assert len(state.frame) == result.ops[0].rows_after

    second = undo_last_cleaning_step(state, workspace)
    assert second is not None and second.op == "dedupe"
    assert len(state.frame) == before
    assert len(state.frame) == 195

    assert undo_last_cleaning_step(state, workspace) is None
    assert not any(step.tab == "cleaning" for step in state.steps)
